sections.css:
.cbf-invoice-rail {
  flex: 0 0 260px;
  border-right: 1px solid var(--color-border);
  padding: var(--spacing-600) var(--spacing-500);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-600);
  background: var(--color-surface-sunken, #f8f9fb);
}
.cbf-stepper {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.cbf-stepper__item {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
}
.cbf-stepper__circle {
  flex: none;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--color-border);
  background: var(--color-surface);
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}
.cbf-stepper__item.is-active .cbf-stepper__circle {
  background: var(--color-primary);
  border-color: var(--color-primary);
}
.cbf-stepper__check {
  display: none;
  color: var(--color-surface);
}
.cbf-stepper__num {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-muted);
  line-height: 1;
}
.cbf-stepper__item.is-active .cbf-stepper__num {
  color: var(--color-surface);
}
.cbf-stepper__label {
  font-size: 14px;
  font-weight: var(--font-weight-medium);
  color: var(--color-text-muted);
  transition: color 0.15s ease;
}
.cbf-stepper__item.is-active .cbf-stepper__label {
  color: var(--color-text-primary);
  font-weight: var(--font-weight-semibold);
}
.cbf-stepper__line {
  width: 2px;
  height: 28px;
  background: var(--color-border);
  margin-left: 13px;
  margin-block: 2px;
  border-radius: 1px;
  transition: background 0.15s ease;
}
.cbf-vendor-card {
  padding: var(--spacing-400);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  background: var(--color-surface);
}
.cbf-vendor-card__eyebrow {
  margin: 0 0 var(--spacing-150);
  font-size: 11px;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}
.cbf-vendor-card__name {
  margin: 0 0 var(--spacing-150);
  font-size: 13px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  line-height: 1.35;
}
.cbf-vendor-card__contact {
  margin: 0;
  font-size: 12px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}
.cbf-vendor-card__email {
  margin: 0;
  font-size: 12px;
  color: var(--color-text-muted);
  line-height: 1.5;
}

.cbf-pdf-panel {
  flex: 1;
  min-width: 0;
  border-right: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  position: relative;
}
.cbf-pdf-panel {
  background: var(--color-surface-sunken, #f8f9fb);
}
.cbf-pdf-panel[hidden] {
  display: none;
}
.cbf-pdf-drop {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-300);
  text-align: center;
  margin: var(--spacing-500);
  padding: var(--spacing-700) var(--spacing-600);
  border: 2px dashed var(--color-border);
  border-radius: var(--radius-100);
  background: var(--color-surface);
  transition:
    border-color 0.15s ease,
    background 0.15s ease;
}
.cbf-pdf-drop__input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-pdf-drop__icon {
  color: var(--color-text-muted);
}
.cbf-pdf-drop__heading {
  margin: 0;
  font-size: 16px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
}
.cbf-pdf-drop__sub {
  margin: 0;
  font-size: 14px;
  color: var(--color-text-secondary);
}
.cbf-pdf-drop__browse {
  color: var(--color-secondary);
  font-weight: var(--font-weight-semibold);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.cbf-pdf-drop__hint {
  margin: 0;
  font-size: 12px;
  color: var(--color-text-muted);
}
.cbf-pdf-viewer {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.cbf-pdf-viewer[hidden] {
  display: none;
}

.esa-button {
  --_btn-height: var(--form-height-md, 40px);
  --_btn-padding-x: var(--form-padding-x-md, 16px);
  --_btn-font-size: var(--form-font-size-md, 14px);
  --_btn-radius: var(--form-radius-md, 6px);
  --_accent: var(--color-primary, #43608a);
  --_accent-hover: var(--color-primary-hover, #39506f);
  --_on: var(--color-text-inverse, #ffffff);
  display: inline-block;
}
.esa-button__native {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  height: var(--_btn-height);
  padding-inline: var(--_btn-padding-x);
  border: 1px solid transparent;
  border-radius: var(--_btn-radius);
  font-size: var(--_btn-font-size);
  font-family: var(--font-sans, system-ui, sans-serif);
  font-weight: var(--font-weight-medium, 500);
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: transparent;
}
.esa-button__label {
  white-space: nowrap;
}
.cbf-page-title {
  margin: 0 0 var(--spacing-400);
  font-family: var(--font-display);
  font-weight: var(--font-weight-medium);
  font-size: 40px;
  line-height: 1;
  letter-spacing: -1px;
  color: var(--color-surface-inverse);
}
.cbf-form-lock {
  display: flex;
  align-items: center;
  gap: var(--spacing-250);
  margin-bottom: var(--spacing-500);
  padding: var(--spacing-300) var(--spacing-400);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  background: var(--color-surface-sunken, #f8f9fb);
  font-size: 13px;
  color: var(--color-text-muted);
  line-height: 1.4;
}
.cbf-form-lock svg {
  flex: none;
  color: var(--color-text-muted);
}
.cbf-form-lock[hidden],
.cbf-form-lock__msg--narrow,
.cbf-form-lock__upload-btn {
  display: none;
}
.cbf-mobile-pdf-input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-form-section {
  margin-top: var(--spacing-600);
  padding-top: var(--spacing-500);
  border-top: 1px solid var(--color-border);
}
.cbf-form-section--first {
  margin-top: 0;
  padding-top: 0;
  border-top: 0;
}
.cbf-form-section__title {
  margin: 0 0 var(--spacing-400);
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: var(--font-weight-medium);
  color: var(--color-text-primary);
  display: flex;
  align-items: baseline;
  gap: var(--spacing-200);
}
.cbf-form-row--2col {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400);
}
.cbf-line-items {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  overflow: hidden;
}
.cbf-line-items__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px 96px 88px 32px;
  gap: var(--spacing-200);
  padding: var(--spacing-300) var(--spacing-400);
  background: var(--color-surface-sunken, #f8f9fb);
  border-bottom: 1px solid var(--color-border);
  font-size: 12px;
  font-weight: var(--font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-text-muted);
}
.cbf-line-items__body {
  display: flex;
  flex-direction: column;
}
.cbf-line-items__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-300) var(--spacing-400);
  border-top: 1px solid var(--color-border);
  background: var(--color-surface-sunken, #f8f9fb);
}
.cbf-add-row {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-150);
  font-size: 14px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-secondary);
  padding: var(--spacing-150) var(--spacing-200);
  border-radius: var(--radius-100);
  transition: background 0.12s ease;
}
.cbf-line-items__total {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
  font-size: 15px;
  color: var(--color-text-secondary);
}
.cbf-line-items__total strong {
  font-size: 17px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
}
.cbf-final-invoice {
  padding: var(--spacing-400) var(--spacing-450, var(--spacing-400));
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  background: var(--color-surface-sunken, #f8f9fb);
  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    box-shadow 0.15s ease;
}
.cbf-optional {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: var(--font-weight-regular);
  color: var(--color-text-muted);
}
.cbf-section-desc {
  margin: calc(-1 * var(--spacing-200)) 0 var(--spacing-400);
  font-size: 14px;
  color: var(--color-text-muted);
  line-height: 1.5;
}
.cbf-support-docs {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  overflow: hidden;
}
.cbf-support-docs__add {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-150);
  font-size: 14px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-secondary);
  padding: var(--spacing-300) var(--spacing-400);
  width: 100%;
  transition: background 0.12s ease;
}
.cbf-docs-input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-step-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
  margin-top: var(--spacing-700);
  padding-top: var(--spacing-500);
  border-top: 1px solid var(--color-border);
}
.cbf-wizard-step--confirm {
  display: flex;
  align-items: flex-start;
}
.cbf-wizard-step--confirm[hidden] {
  display: none;
}
.cbf-line-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px 96px 88px 32px;
  gap: var(--spacing-200);
  padding: var(--spacing-250) var(--spacing-400);
  border-bottom: 1px solid var(--color-border);
  align-items: center;
}
.cbf-line-item:last-child {
  border-bottom: 0;
}
.cbf-li-input {
  box-sizing: border-box;
  width: 100%;
  padding: var(--spacing-150) var(--spacing-250);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  font-family: var(--font-sans);
  font-size: 14px;
  color: var(--color-text-primary);
  background: var(--color-surface);
  transition:
    border-color 0.12s ease,
    box-shadow 0.12s ease;
  outline: none;
}
.cbf-li-input:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  background: var(--color-surface-sunken, #f8f9fb);
}
.cbf-li-input::placeholder {
  color: var(--color-text-muted);
}
.cbf-li-qty,
.cbf-li-price {
  text-align: right;
}
.cbf-li-total {
  font-size: 14px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  text-align: right;
}
.cbf-li-remove {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-100);
  color: var(--color-text-muted);
  transition:
    background 0.12s ease,
    color 0.12s ease;
}
.cbf-add-row:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.cbf-support-docs__add:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.cbf-page-title {
  margin: 0 0 var(--spacing-400);
  font-family: var(--font-display);
  font-weight: var(--font-weight-medium);
  font-size: 40px;
  line-height: 1;
  letter-spacing: -1px;
  color: var(--color-surface-inverse);
}
.cbf-step-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
  margin-top: var(--spacing-700);
  padding-top: var(--spacing-500);
  border-top: 1px solid var(--color-border);
}
.cbf-wizard-step--confirm {
  display: flex;
  align-items: flex-start;
}
.cbf-wizard-step--confirm[hidden] {
  display: none;
}
.esa-button {
  --_btn-height: var(--form-height-md, 40px);
  --_btn-padding-x: var(--form-padding-x-md, 16px);
  --_btn-font-size: var(--form-font-size-md, 14px);
  --_btn-radius: var(--form-radius-md, 6px);
  --_accent: var(--color-primary, #43608a);
  --_accent-hover: var(--color-primary-hover, #39506f);
  --_on: var(--color-text-inverse, #ffffff);
  display: inline-block;
}
.esa-button__native {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  height: var(--_btn-height);
  padding-inline: var(--_btn-padding-x);
  border: 1px solid transparent;
  border-radius: var(--_btn-radius);
  font-size: var(--_btn-font-size);
  font-family: var(--font-sans, system-ui, sans-serif);
  font-weight: var(--font-weight-medium, 500);
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: transparent;
}
.esa-button__label {
  white-space: nowrap;
}

.cbf-wizard-step--confirm {
  display: flex;
  align-items: flex-start;
}
.cbf-wizard-step--confirm[hidden] {
  display: none;
}
